// spec: specs/inventory.md §5
// seed: tests/seed.admin.spec.ts
// inventory · кейс inv-08 (.qa/tests/inventory/) — #d17c625a (עבר QA 2026-10-12), решение владельца 11.10:
//   привязан к месту и остаток 0 → удаляется сразу обычным окном (старое ожидание «блок даже при 0» отменено);
//   привязан и остаток В МЕСТЕ → блок «לא ניתן למחוק מוצר עם מלאי» + «מעבר למפת המחסן».
// Товары «QA-AUTO-d17c-*-<ts>», места — свободные «ריק» полки, найденные на карте во время прогона (шкафы E/F/G).
// ⚠️ Каждая приёмка оставляет НЕУДАЛЯЕМУЮ запись «קליטה» в יומן תנועות — здесь всего 2 (B: 2 шт., R: 1 шт.).
// Уборка — «הסרה מהמקום» (остаток уходит в «ללא מקום», без списаний) и удаление; места снова «ריק».
// Не запускать одновременно с inventory-lifecycle / order-lifecycle / cart-checkout (общие данные склада).
import { test, expect } from '@playwright/test';
import * as H from './_places';

test.use({ storageState: H.ADMIN });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const CABINETS = ['E', 'F', 'G'];
const A1 = `QA-AUTO-d17c-A1-${TS}`; // 1 место, 0
const A2 = `QA-AUTO-d17c-A2-${TS}`; // 2 места, 0
const B = `QA-AUTO-d17c-B-${TS}`; // 1 место, 2 шт. в месте
const R = `QA-AUTO-d17c-R-${TS}`; // гонка: окно открыто, в это время приход в место
const created = new Set<string>();
const used: H.Used = new Map();
let placeB: H.Place | null = null;

test.describe('inventory — מחיקת מוצר שמשויך למקום במחסן (#d17c625a)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(300_000);
    await H.cleanup(browser, created, used);
  });

  test('משויך למקום אחד, מלאי 0 → «מחיקה» רגיל → «מחיקת מוצר» → נמחק (delete_product 200), המקום «ריק» #d17c625a @desktop @data', async ({ page }) => {
    test.setTimeout(180_000);
    const [pl] = await H.pickEmptyPlaces(page, 1, CABINETS);
    await H.createProduct(page, A1, `QAD17A1${TS}`, created);
    H.track(used, A1, pl);
    await H.bindPlace(page, A1, pl);
    await H.findProduct(page, A1);
    await expect(H.row(page, A1)).toContainText(pl.code);
    await expect(H.qtyBtn(page, A1)).toHaveText('0');

    const del = await H.openRowMenuDelete(page, A1);
    await expect(del).not.toContainText('יש מלאי במחסן');
    await del.click();
    const dlg = page.getByRole('dialog');
    await H.expectPlainDeleteDialog(dlg, A1);
    // «ביטול» — ничего не удаляется
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
    await expect(H.qtyBtn(page, A1)).toBeVisible();

    await (await H.openRowMenuDelete(page, A1)).click();
    await H.expectPlainDeleteDialog(dlg, A1);
    await H.confirmDelete(page, A1);
    created.delete(A1);

    const label = await H.openPlace(page, pl);
    expect(label[label.length - 1], `${pl.code} «ריק» после удаления`).toBe('ריק');
  });

  test('משויך לשני מקומות («הוספת מיקום»), מלאי 0 → נמחק בחלון רגיל, שני המקומות «ריק» #d17c625a @desktop @data', async ({ page }) => {
    test.setTimeout(240_000);
    const [p1, p2] = await H.pickEmptyPlaces(page, 2, CABINETS);
    await H.createProduct(page, A2, `QAD17A2${TS}`, created);
    H.track(used, A2, p1, p2);
    await H.bindPlace(page, A2, p1);
    await H.bindPlace(page, A2, p2, true);
    await H.findProduct(page, A2);
    await expect(H.row(page, A2)).toContainText(p1.code);
    await expect(H.row(page, A2)).toContainText(p2.code);

    const del = await H.openRowMenuDelete(page, A2);
    await expect(del).not.toContainText('יש מלאי במחסן');
    await del.click();
    await H.expectPlainDeleteDialog(page.getByRole('dialog'), A2);
    await H.confirmDelete(page, A2);
    created.delete(A2);

    for (const pl of [p1, p2]) {
      const label = await H.openPlace(page, pl);
      expect(label[label.length - 1], `${pl.code} «ריק» после удаления`).toBe('ריק');
    }
  });

  test('משויך + 2 במקום → «מחיקה · יש מלאי במחסן» → «לא ניתן למחוק מוצר עם מלאי», שורת «<קוד> · 2», «סגירה» #d17c625a @desktop @data', async ({ page }) => {
    test.setTimeout(240_000);
    const [pl] = await H.pickEmptyPlaces(page, 1, CABINETS);
    placeB = pl;
    await H.createProduct(page, B, `QAD17B${TS}`, created);
    H.track(used, B, pl);
    await H.bindPlace(page, B, pl);
    await H.receive(page, B, 2, pl.code);

    const del = await H.openRowMenuDelete(page, B);
    await expect(del).toContainText('יש מלאי במחסן');
    await del.click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: H.BLOCK })).toBeVisible({ timeout: 20_000 });
    await expect(dlg).toContainText(B);
    await expect(dlg).toContainText('— משויך למקום במחסן, ורשומות בו עדיין 2.');
    const items = dlg.getByRole('listitem');
    await expect(items).toHaveCount(1);
    await expect(items.first()).toContainText(new RegExp(`${pl.code}\\s*· 2$`)); // «קומה 1 | ארון X | <מדף> | <קוד> · 2»
    await expect(dlg.getByRole('button', { name: 'סגירה' })).toBeVisible();
    await expect(dlg.getByRole('button', { name: 'מעבר למפת המחסן' })).toBeVisible();
    await expect(dlg.getByRole('button', { name: 'מחיקה', exact: true })).toHaveCount(0);
    await dlg.getByRole('button', { name: 'סגירה' }).click();
    await expect(dlg).toHaveCount(0);
    await expect(H.qtyBtn(page, B)).toHaveText('2');
  });

  test('«מעבר למפת המחסן» → המקום נבחר במפה → «הסרה מהמקום» → בקטלוג «ללא מיקום» → נמחק בחלון רגיל #d17c625a @desktop @data', async ({ page }) => {
    test.setTimeout(240_000);
    test.skip(!placeB || !created.has(B), 'товар B не подготовлен');
    await H.findProduct(page, B);
    await (await H.openRowMenuDelete(page, B)).click();
    await page.getByRole('dialog').getByRole('button', { name: 'מעבר למפת המחסן' }).click();
    await expect(page).toHaveURL(/\/warehouse\/map/);
    // открыта панель именно этого места: товар в ней, с «הסרה מהמקום»
    await expect(H.side(page).getByRole('heading', { name: 'תכולת המדף' })).toBeVisible({ timeout: 30_000 });
    await expect(H.side(page)).toContainText(placeB!.code);
    expect(await H.qtyInPlacePanel(page, B)).toBe(2);
    await H.unplaceInPanel(page, B, true);

    await H.findProduct(page, B);
    await expect(H.row(page, B)).toContainText('ללא מיקום');
    await expect(H.qtyBtn(page, B)).toHaveText('2'); // остаток остался, без места
    const del = await H.openRowMenuDelete(page, B);
    await expect(del).not.toContainText('יש מלאי במחסן');
    await del.click();
    await H.expectPlainDeleteDialog(page.getByRole('dialog'), B);
    await H.confirmDelete(page, B, true); // есть движения → архив, «הוסר מהקטלוג»
    created.delete(B);
  });

  test('בדיקת שרת: חלון «מחיקת מוצר» פתוח (משויך, 0), בינתיים נקלטה יחידה למקום → 400 PRODUCT_HAS_STOCK → חלון החסימה עם «מעבר למפת המחסן», המוצר לא נמחק #d17c625a @desktop @data', async ({ page }) => {
    test.setTimeout(240_000);
    const [pl] = await H.pickEmptyPlaces(page, 1, CABINETS);
    await H.createProduct(page, R, `QAD17R${TS}`, created);
    H.track(used, R, pl);
    await H.bindPlace(page, R, pl);
    await H.findProduct(page, R);
    await (await H.openRowMenuDelete(page, R)).click();
    const dlg = page.getByRole('dialog');
    await H.expectPlainDeleteDialog(dlg, R);

    // другая вкладка той же сессии: приход 1 шт. в место, пока окно удаления открыто
    const other = await page.context().newPage();
    try {
      await H.receive(other, R, 1, pl.code);
    } finally {
      await other.close();
    }

    const respP = page.waitForResponse((r) => r.url().includes('/rpc/delete_product') && r.request().method() === 'POST');
    await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
    const resp = await respP;
    expect(resp.status()).toBe(400);
    expect(await resp.text()).toContain('PRODUCT_HAS_STOCK');
    await expect(dlg.getByRole('heading', { name: H.BLOCK })).toBeVisible({ timeout: 15_000 });
    await expect(dlg.getByRole('button', { name: 'מעבר למפת המחסן' })).toBeVisible();
    await expect(page.getByText(new RegExp(`${R}\\W{0,3} נמחק\\.`))).toHaveCount(0);
    await page.keyboard.press('Escape');

    await H.expectStock(page, R, 1); // товар не удалён
  });
});
